const staticData = $getWorkflowStaticData('global');
staticData.seen = staticData.seen || [];

const viewers = $input.first().json.viewers || [];
const newViewers = [];

for (const v of viewers) {
  if (!staticData.seen.includes(v.profileUrl)) {
    staticData.seen.push(v.profileUrl);
    newViewers.push(v);
  }
}

if (staticData.seen.length > 500) {
  staticData.seen = staticData.seen.slice(-500);
}

if (newViewers.length === 0) {
  return [];
}

return newViewers.map(v => ({ json: v }));

